module tb_TopModule;
    logic [15:0] a, b, c, d, e, f, g, h, i;
    logic [3:0]  sel;
    logic [15:0] out;

    TopModule uut (
        .a(a), .b(b), .c(c), .d(d), .e(e), .f(f), .g(g), .h(h), .i(i),
        .sel(sel), .out(out)
    );

    initial begin
        a = 16'h0001;
        b = 16'h0002;
        c = 16'h0004;
        d = 16'h0008;
        e = 16'h0010;
        f = 16'h0020;
        g = 16'h0040;
        h = 16'h0080;
        i = 16'h0100;

        for (int s = 0; s < 16; s++) begin
            sel = s[3:0];
            #1;
            case (sel)
                4'd0: if (out !== a) $display("Error sel=0: expected %h, got %h", a, out);
                4'd1: if (out !== b) $display("Error sel=1: expected %h, got %h", b, out);
                4'd2: if (out !== c) $display("Error sel=2: expected %h, got %h", c, out);
                4'd3: if (out !== d) $display("Error sel=3: expected %h, got %h", d, out);
                4'd4: if (out !== e) $display("Error sel=4: expected %h, got %h", e, out);
                4'd5: if (out !== f) $display("Error sel=5: expected %h, got %h", f, out);
                4'd6: if (out !== g) $display("Error sel=6: expected %h, got %h", g, out);
                4'd7: if (out !== h) $display("Error sel=7: expected %h, got %h", h, out);
                4'd8: if (out !== i) $display("Error sel=8: expected %h, got %h", i, out);
                default: if (out !== 16'hFFFF) $display("Error sel=%0d: expected FFFF, got %h", sel, out);
            endcase
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
